 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The shapes are 5-pixel-wide/15-pixel-tall objects made by a path of 5s
    # dividing small 0 pockets. Recolor the 10-cell pocket in the lower section
    # as 8; the isolated lower-left endpoint is 7.
    # Locate 4-connected 0 components and recolor the unique 10-cell one.
    from collections import deque
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            if len(cells)==10:
                for x,y in cells: out[x][y]=8
    # Bottom-left isolated zero gets the 7 accent when it is between 5s.
    if h>=2 and w>=2 and grid[h-1][0]==0 and grid[h-2][0]==5 and grid[h-1][1]==5:
        out[h-1][0]=7
    return out
