    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            # The unique 10-cell winding pocket is marked with 8 when it is
            # the pocket enclosed by the larger 5-connected stroke.
            if len(cells)==10 and h >= 10:
                for x,y in cells: out[x][y]=8
    # The demo has a single lower-left endpoint zero immediately flanked by 5.
    if h and w and grid[h-1][0] == 0:
        ns=[grid[x][y] for x,y in ((h-2,0),(h-1,1)) if 0<=x<h and 0<=y<w]
        if len(ns)==2 and all(v==5 for v in ns): out[h-1][0]=7
    return out
